const E=Sovereign,W=E.W,$=id=>document.getElementById(id),ico=(name,cl='')=>'<svg class="icon '+cl+'"><use href="#i-'+name+'"/></svg>',esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),fmt=n=>Math.round(n).toLocaleString('fr-FR'),time=n=>Math.max(0,Math.ceil(n))+' s',timerText=n=>String(Math.floor(n/60)).padStart(2,'0')+':'+String(Math.floor(n%60)).padStart(2,'0');
let state=E.create(),player='FR',started=false,online=false,room=null,roomMembers=[],paused=false,speed=1,busy=false,activePanel=null,targetCountry=null,selected=null,selectedUnit=null,orderUnit=null,chatTarget=null,chosen='FR',startMode='local',saved=null,savedOnline=null,saveOK=true;
