const canvas=$('map'),ctx=canvas.getContext('2d'),modal=$('modal');let view={zoom:1,x:0,y:0},width=1,height=1,dpr=1,baseScale=1,political=true,geoPaths=[],hover=null,unitHits=[],lastTick=performance.now(),lastDraw=0,lastHUD=0,lastSave=0,lastAI=0,notifyTimer=0,pollTimer=null,pollFailures=0,receivedAt=performance.now();const touches=new Map();let drag=null,pinch=null;
const cx=13,cy=-74;
function flag(code){let svg='';const stripes={FR:['#355fa1','#f0eee5','#be555b','v'],DE:['#1e2527','#b74b47','#d4b65e','h'],IT:['#528268','#eeeae0','#b25854','v'],ES:['#a54d45','#d0ad55','#a54d45','h'],PL:['#f1efe7','#b95364','h'],UA:['#4981a1','#d4b656','h'],RO:['#325888','#d2b45b','#b64b4e','v'],BE:['#252524','#ccb158','#af4d4b','v'],NL:['#b55854','#ebe9df','#4f6e9a','h'],AT:['#b55b5b','#eeeade','#b55b5b','h'],HU:['#b35b58','#e8e5d9','#618269','h'],BG:['#e8e6d9','#658771','#ae5957','h'],IE:['#658972','#eae7df','#c2905d','v'],LT:['#c4ad5c','#67886b','#af5c57','h'],LV:['#8c4d59','#e8e5dc','#8c4d59','h'],EE:['#6188a6','#283037','#e7e9e1','h'],RS:['#b25655','#527390','#e5e5dc','h'],SK:['#e9e5df','#507499','#b95e5c','h'],HR:['#b65352','#e5e5dc','#507292','h']};
 if(stripes[code]){const arr=[...stripes[code]],dir=arr.pop(),n=arr.length;svg=arr.map((color,i)=>'<rect x="'+(dir==='v'?30*i/n:0)+'" y="'+(dir==='h'?20*i/n:0)+'" width="'+(dir==='v'?30/n:30)+'" height="'+(dir==='h'?20/n:20)+'" fill="'+color+'"/>').join('');}
 const cross={SE:['#507695','#d7be71'],NO:['#a45455','#345775'],FI:['#e7e5db','#557394'],DK:['#aa5455','#e5e6da'],CH:['#b85b54','#eeece3']};if(cross[code]){const[a,b]=cross[code];svg='<rect width="30" height="20" fill="'+a+'"/>';if(code==='CH')svg+='<path d="M12 4h6v4h4v5h-4v4h-6v-4H8V8h4z" fill="'+b+'"/>';else{if(code==='NO')svg+='<path d="M8 0h7v20H8zM0 7h30v7H0z" fill="#e8e6dc"/>';svg+='<path d="M10 0h3v20h-3zM0 9h30v3H0z" fill="'+b+'"/>';}}
 if(code==='GB')svg='<rect width="30" height="20" fill="#456380"/><path d="M0 0l30 20M30 0L0 20" stroke="#e7e5db" stroke-width="4"/><path d="M0 0l30 20M30 0L0 20" stroke="#b65a59" stroke-width="1.6"/><path d="M15 0v20M0 10h30" stroke="#e7e5db" stroke-width="6"/><path d="M15 0v20M0 10h30" stroke="#b65a59" stroke-width="3"/>';
 if(code==='PT')svg='<rect width="30" height="20" fill="#b65455"/><rect width="12" height="20" fill="#537b61"/><circle cx="12" cy="10" r="4" fill="#cbb569"/>';
 if(code==='GR')svg=Array.from({length:9},(_,i)=>'<rect y="'+(20*i/9)+'" width="30" height="'+20/9+'" fill="'+(i%2?'#e4e6db':'#5c82a2')+'"/>').join('')+'<rect width="12" height="11" fill="#5c82a2"/><path d="M5 0h2v11H5zM0 4.5h12v2H0z" fill="#e4e6db"/>';
 if(code==='CZ')svg='<rect width="30" height="10" fill="#e9e7de"/><rect y="10" width="30" height="10" fill="#b85955"/><path d="M0 0l14 10L0 20z" fill="#526f93"/>';
 return '<svg class="flag" viewBox="0 0 30 20" aria-label="'+esc(E.country(code)?.name||code)+'">'+svg+'</svg>';}
function toast(text){$('toast').textContent=text;$('toast').classList.add('visible');clearTimeout(notifyTimer);notifyTimer=setTimeout(()=>$('toast').classList.remove('visible'),3600);}
function save(){if(!started||online)return;try{localStorage.setItem('souverain-europe-save',JSON.stringify({state,player}));saved={state,player};}catch{if(saveOK){toast('Sauvegarde locale indisponible : exportez une copie dans les paramètres.');saveOK=false;}}}
function netData(result){if(!result||!E.valid(result.state))throw new Error('État de partie incompatible. Réinstallez supabase.sql dans un projet dédié.');state=result.state;player=result.country;room=result.code;roomMembers=result.members||[];online=true;started=true;paused=false;speed=1;pollFailures=0;receivedAt=performance.now();try{localStorage.setItem('souverain-europe-room',JSON.stringify({code:room,country:player}));savedOnline={code:room,country:player};}catch{}if(selectedUnit&&!state.units.some(u=>u.id===selectedUnit))selectedUnit=null;}
async function send(a,success){if(!started){welcome();return false;}if(busy){toast('Un ordre est déjà en cours de transmission.');return false;}
 if(online){busy=true;try{netData(await Online.rpc('sovereign_sync',{p_code:room,p_action:a}));refresh(true);if(success)toast(success);return true;}catch(e){toast(e.message);return false;}finally{busy=false;}}
 const err=E.action(state,player,a);if(err){toast(err);return false;}save();refresh(true);if(success)toast(success);return true;}
function startPolling(){clearInterval(pollTimer);pollTimer=setInterval(async()=>{if(!online||busy||document.hidden)return;busy=true;try{netData(await Online.rpc('sovereign_sync',{p_code:room,p_action:null}));refresh(false);}catch(e){pollFailures++;$('mode').innerHTML='<i style="background:var(--red)"></i> CONNEXION INTERROMPUE';if(pollFailures===1)toast('Connexion interrompue : '+e.message);}finally{busy=false;}},3000);}
function header(){const c=state.countries[player],inc=E.income(state,player);$('nation-switch').innerHTML=flag(player)+'<div><b>'+E.country(player).name+'</b><small>'+ (started?esc(c.leader):'Choisissez votre gouvernement')+'</small></div>';
 $('resources').innerHTML=Object.entries(E.names).map(([k,label],i)=>'<div class="resource"><span>'+['◇','▥','◉','✚'][i]+'</span><b>'+fmt(c[k])+(k==='credits'?' €':'')+'</b><small>'+label+' <em class="'+(inc[k]<0?'negative':'')+'">'+(inc[k]>=0?'+':'')+fmt(inc[k])+'/min</em></small></div>').join('');$('clock').textContent=timerText(state.clock);$('mode').innerHTML='<i'+(online?' style="background:var(--green)"':'')+'></i> '+(online?'SALON '+room:'ENTRAÎNEMENT');$('pause').textContent=paused?'▶':'Ⅱ';$('pause').disabled=online;$('speed').disabled=online;$('speed').textContent='×'+speed;$('room-info').textContent=online?'INVITER':'LOCAL';$('briefing-text').textContent=state.news[0]?.title||'Les négociations sont ouvertes.';$('map-subtitle').textContent=started?'Commandement de '+E.country(player).name+' · '+E.provinces(state,player).length+' secteurs':'Choisissez votre nation pour commencer.';
 const count=state.proposals.filter(t=>t.to===player).length;$('treaty-count').hidden=!count;$('treaty-count').textContent=count;document.querySelectorAll('[data-remaining]').forEach(el=>{el.textContent=time(Number(el.dataset.remaining)-visualClock());});}
function refresh(force=false){header();renderDrawer(!force);renderContext();renderUnit();dirty=true;}
function openPanel(name){if(!started){welcome();return;}activePanel=activePanel===name?null:name;targetCountry=null;renderDrawer(false);}
function drawerHead(eyebrow,title,desc){return '<div class="drawer-header"><span class="eyebrow">'+eyebrow+'</span><button class="close" data-action="close-panel" aria-label="Fermer">'+ico('cross')+'</button></div><h2>'+title+'</h2><p class="intro">'+desc+'</p>';}
function provinceSelect(){const own=E.provinces(state,player);return '<label for="sector-select">Secteur de production</label><select id="sector-select">'+own.map(p=>'<option value="'+p.id+'" '+(p.id===(selected&&state.provinces[selected].owner===player?selected:own[0]?.id)?'selected':'')+'>'+p.name+(p.capital?' · capitale':'')+'</option>').join('')+'</select>';}
function queueHTML(){const queue=state.queue.filter(q=>q.country===player);return queue.length?queue.map(q=>{const b=(q.type==='build'?E.buildings:E.units)[q.item],progress=Math.max(0,Math.min(100,100*(1-(q.due-state.clock)/b.seconds)));return '<div class="list-entry"><div>'+esc(b.name)+'<small>'+esc(E.meta(q.province).name)+' · <span data-remaining="'+q.due+'">'+time(q.due-state.clock)+'</span></small><div class="queuebar"><i style="width:'+progress+'%"></i></div></div><button class="close" data-action="cancel-queue" data-id="'+q.id+'" title="Annuler et récupérer 75 % du coût">'+ico('cross')+'</button></div>';}).join(''):'<div class="empty">Aucune préparation en cours.</div>';}
function cost(c){return Object.entries(c).map(([k,v])=>fmt(v)+(k==='credits'?' €':' '+({industry:'IND',fuel:'CAR',supply:'RAV'}[k]))).join(' · ');}
function nationPanel(){const c=state.countries[player],count=E.provinces(state,player).length;return drawerHead('CABINET NATIONAL','Votre gouvernement','Les décisions nationales influencent les ressources et le soutien de la population.')+'<div class="nation-leader">'+flag(player)+'<div><h3>'+E.country(player).name+'</h3><small>'+esc(c.leader)+'</small></div></div><div class="metric"><span>Soutien de la population</span><b>'+Math.round(c.approval)+' %</b></div><div class="progress"><i style="width:'+c.approval+'%;background:'+(c.approval<30?'var(--red)':'var(--green)')+'"></i></div><p class="muted">'+(c.approval<30?'Les troubles réduisent les recettes de 30 %.':'Maintenez les services publics et les réserves de ravitaillement.')+'</p><div class="divider"></div><label for="tax">Prélèvement fiscal <b id="tax-label">'+c.tax+' %</b></label><input type="range" id="tax" min="10" max="35" value="'+c.tax+'"><p class="muted">Au-dessus de 20 %, le soutien baisse progressivement. En dessous, il remonte.</p><label for="policy">Priorité du gouvernement</label><select id="policy"><option value="balanced" '+(c.policy==='balanced'?'selected':'')+'>Équilibre budgétaire</option><option value="industrial" '+(c.policy==='industrial'?'selected':'')+'>Industrie · +20 IND, −90 €/min</option><option value="social" '+(c.policy==='social'?'selected':'')+'>Social · +1,2 soutien, −120 €/min</option></select><div class="metric"><span>Secteurs contrôlés</span><b>'+count+' / 72</b></div><div class="metric"><span>Unités opérationnelles</span><b>'+state.units.filter(u=>u.owner===player).length+'</b></div><div class="metric"><span>Conflits actifs</span><b>'+W.countries.filter(c=>c.id!==player&&E.relation(state,player,c.id).status==='war').length+'</b></div><div class="goal"><strong>Objectif stratégique</strong><p>Contrôlez 40 secteurs pour devenir la puissance dominante. Diplomatie et économie permettent de préparer vos opérations.</p></div><div class="section-head"><h3>Marché des ressources</h3></div><label for="market-resource">Ressource</label><select id="market-resource"><option value="industry">Industrie · 6 € / unité</option><option value="fuel">Carburant · 5 € / unité</option><option value="supply">Ravitaillement · 3 € / unité</option></select><label for="market-amount">Quantité</label><select id="market-amount"><option>25</option><option>50</option><option>100</option></select><div class="row" style="margin-top:10px"><button class="primary small" data-action="market" data-buy="true">Acheter</button><button class="small" data-action="market" data-buy="false">Vendre à 70 %</button></div>';}
function constructionPanel(){const own=E.provinces(state,player),id=selected&&state.provinces[selected].owner===player?selected:own[0]?.id;if(!id)return drawerHead('INDUSTRIE','Gouvernement en exil','Vous ne contrôlez plus aucun secteur.');const p=state.provinces[id];return drawerHead('ÉCONOMIE DE TERRAIN','Industrie & services','Choisissez un secteur, puis investissez. Les délais correspondent au rythme du jeu, pas aux durées réelles.')+provinceSelect()+Object.entries(E.buildings).map(([item,b])=>{const level=p.buildings[item]||0;return '<div class="card"><div class="card-head"><div>'+ico(item==='fort'?'nation':'build')+'<h3>'+b.name+'</h3></div><small>'+b.seconds+' s</small></div><p>'+b.desc+' · niveau '+level+'/3</p><p class="cost">'+cost(b.cost)+'</p><button class="full small '+(level<3?'primary':'')+'" data-action="build" data-item="'+item+'" '+(level>=3||!E.afford(state,player,b.cost)?'disabled':'')+'>'+(level>=3?'Niveau maximum':'Construire · '+b.seconds+' s')+'</button></div>';}).join('')+'<div class="section-head"><h3>Préparations en cours</h3></div>'+queueHTML();}
function militaryPanel(){const own=E.provinces(state,player);return drawerHead('ÉTAT-MAJOR','Forces & opérations','Sélectionnez une unité, puis cliquez sa destination sur la carte. Les itinéraires passent par vos secteurs et ceux de vos alliés.')+(own.length?provinceSelect()+Object.entries(E.units).map(([item,u])=>'<div class="card"><div class="card-head"><div>'+ico(u.icon)+'<h3>'+u.name+'</h3></div><small>'+u.seconds+' s</small></div><p>Puissance '+u.power+' · entretien '+u.upkeep+' €/min</p><p class="cost">'+cost(u.cost)+'</p><button class="full small primary" data-action="recruit" data-item="'+item+'" '+(!E.afford(state,player,u.cost)?'disabled':'')+'>Préparer · '+u.seconds+' s</button></div>').join(''):'<div class="empty">Vous n’avez plus de secteur de recrutement.</div>')+'<div class="section-head"><h3>Vos unités</h3><small>'+state.units.filter(u=>u.owner===player).length+'</small></div><div class="unit-list" style="max-height:320px">'+state.units.filter(u=>u.owner===player).map(u=>'<button data-action="select-unit" data-id="'+u.id+'">'+ico(u.type==='armor'?'tank':u.type)+'<span>'+esc(u.name)+'<small style="display:block">'+(u.moving?'Vers '+E.meta(u.moving.target).name+' · '+time(u.moving.due-state.clock):E.meta(u.province).name)+'</small></span><b>'+Math.round(u.hp)+' %</b></button>').join('')+'</div><div class="section-head"><h3>Préparations</h3></div>'+queueHTML();}
function treatyName(k){return {trade:'Accord commercial',alliance:'Alliance militaire',peace:'Cessez-le-feu'}[k];}
function statusLabel(r){return {peace:'En paix',alliance:'Allié',war:'En guerre',self:'Votre pays'}[r.status];}
function diplomacyPanel(){const proposals=state.proposals.filter(t=>t.to===player);const inbox=proposals.map(t=>'<div class="card"><div class="card-head"><h3>'+treatyName(t.kind)+'</h3><span class="pill">À SIGNER</span></div><p>Proposé par '+E.country(t.from).name+'</p><div class="row"><button class="primary small" data-action="respond" data-id="'+t.id+'" data-accept="true">Signer</button><button class="small" data-action="respond" data-id="'+t.id+'" data-accept="false">Refuser</button></div></div>').join('');
 if(!targetCountry)return drawerHead('AFFAIRES ÉTRANGÈRES','Diplomatie','Un traité avec un joueur attend sa signature. Un gouvernement simulé répond sous 8 secondes.')+inbox+W.countries.filter(c=>c.id!==player).map(c=>{const r=E.relation(state,player,c.id);return '<button class="country-entry" data-action="country-dip" data-id="'+c.id+'">'+flag(c.id)+'<b>'+c.name+'</b><small>'+statusLabel(r)+(state.members[c.id]?' · joueur':'')+'</small></button>';}).join('');
 const id=targetCountry,n=E.country(id),r=E.relation(state,player,id);return drawerHead('RELATIONS BILATÉRALES',n.name,esc(state.countries[id].leader))+'<button class="small" data-action="dip-back">← Tous les pays</button><div class="metric"><span>Statut diplomatique</span><span class="pill '+(r.status==='war'?'red':r.status==='alliance'?'green':'blue')+'">'+statusLabel(r)+'</span></div><div class="metric"><span>Relations</span><b>'+r.value+' / 100</b></div><div class="metric"><span>Gouvernement</span><b>'+(state.members[id]?'Joueur connecté au salon':online?'Neutre / réponses automatiques':'Simulé')+'</b></div>'+(r.truce>state.clock?'<div class="note">Trêve active · <span data-remaining="'+r.truce+'">'+time(r.truce-state.clock)+'</span></div>':'')+inbox+'<div class="divider"></div><div class="card"><h3>Mission diplomatique</h3><p>300 € · +15 points de relations. Facilite les accords avec les gouvernements simulés.</p><button class="full small" data-action="diplomacy" data-kind="delegation" '+(r.status==='war'?'disabled':'')+'>Envoyer une délégation</button></div><div class="card"><h3>Accord commercial</h3><p>+90 €/min et +8 industrie/min pour chacun. Acceptation automatique à 45 relations ; un joueur décide librement.</p><button class="full small primary" data-action="diplomacy" data-kind="trade" '+(r.trade||r.status==='war'?'disabled':'')+'>'+(r.trade?'Accord actif':'Proposer le commerce')+'</button></div><div class="card"><h3>Alliance militaire</h3><p>Autorise le transit dans les secteurs alliés. Acceptation automatique à 70 relations. Pas d’intervention militaire automatique.</p><button class="full small primary" data-action="diplomacy" data-kind="alliance" '+(r.status==='alliance'||r.status==='war'?'disabled':'')+'>Proposer une alliance</button></div>'+(r.status==='war'?'<button class="full small blue" data-action="diplomacy" data-kind="peace">Proposer un cessez-le-feu</button>':'<button class="full small danger" data-action="war-modal" '+(r.truce>state.clock?'disabled':'')+'>Déclarer la guerre</button>')+'<button class="full small" style="margin-top:10px" data-action="direct-chat" data-id="'+id+'">'+ico('chat')+' Ouvrir un canal diplomatique</button><div class="section-head"><h3>Propositions en attente</h3></div>'+(state.proposals.filter(t=>t.from===player&&t.to===id).map(t=>'<div class="list-entry">'+treatyName(t.kind)+'<small>'+(t.due===null?'Attend la signature du joueur':'<span data-remaining="'+t.due+'">'+time(t.due-state.clock)+'</span>')+'</small></div>').join('')||'<div class="empty">Aucune proposition en cours.</div>');}
function newsPanel(){return drawerHead('LE JOURNAL EUROPÉEN','La voix des nations','Publiez vos discours et les annonces officielles de votre gouvernement.')+'<button class="full primary small" data-action="compose">Rédiger un communiqué</button>'+state.news.slice(0,50).map(n=>'<article class="card news-card"><div class="news-meta"><span>'+esc(n.author)+'</span><span>'+timerText(n.at)+'</span></div><h3>'+esc(n.title)+'</h3><p>'+esc(n.body)+'</p></article>').join('');}
function chatPanel(){const messages=(state.messages||[]).filter(m=>chatTarget?m.from===player&&m.to===chatTarget||m.from===chatTarget&&m.to===player:!m.to);return drawerHead('CANAL DIPLOMATIQUE',chatTarget?E.country(chatTarget).name:'Salle des dirigeants',online?'Messages du salon, synchronisés avec les autres joueurs.': 'En entraînement, vos messages sont archivés localement. Les gouvernements simulés ne répondent pas.')+'<label for="chat-channel">Destinataire</label><select id="chat-channel"><option value="">Tous les dirigeants</option>'+W.countries.filter(c=>c.id!==player).map(c=>'<option value="'+c.id+'" '+(chatTarget===c.id?'selected':'')+'>'+c.name+'</option>').join('')+'</select><div class="divider"></div><div id="chat-messages">'+(messages.length?messages.slice(-40).map(m=>'<div class="message"><small>'+esc(state.countries[m.from].leader)+' · '+timerText(m.at)+'</small><p>'+esc(m.body)+'</p></div>').join(''):'<div class="empty">Ouvrez les négociations avec un premier message.</div>')+'</div><label for="chat-body">Votre message</label><textarea id="chat-body" rows="3" maxlength="500" placeholder="Bonjour, nous souhaitons discuter…"></textarea><button class="full small primary" style="margin-top:10px" data-action="chat-send">Transmettre</button>';}
function renderDrawer(preserve=true){const drawer=$('drawer'),focused=document.activeElement?.id,caretStart=document.activeElement?.selectionStart,caretEnd=document.activeElement?.selectionEnd,scroll=drawer.scrollTop,fields={};if(preserve)drawer.querySelectorAll('input,textarea,select').forEach(e=>{if(e.id)fields[e.id]=e.value;});drawer.hidden=!activePanel;document.querySelectorAll('[data-panel]').forEach(b=>b.classList.toggle('active',b.dataset.panel===activePanel));if(!activePanel)return;const panels={nation:nationPanel,construction:constructionPanel,military:militaryPanel,diplomacy:diplomacyPanel,news:newsPanel,chat:chatPanel};drawer.innerHTML=panels[activePanel]();if(preserve){for(const[id,value]of Object.entries(fields))if($(id))$(id).value=value;drawer.scrollTop=scroll;if(focused&&$(focused)){$(focused).focus({preventScroll:true});if(typeof caretStart==='number'&&$(focused).setSelectionRange)$(focused).setSelectionRange(caretStart,caretEnd);}}}
function renderContext(){const box=$('context');box.hidden=!selected||!started||Boolean(orderUnit);document.body.classList.toggle('context-open',!box.hidden);if(box.hidden)return;const m=E.meta(selected),p=state.provinces[selected],ours=p.owner===player,localUnits=state.units.filter(u=>u.province===selected&&!u.moving),r=E.relation(state,player,p.owner);box.innerHTML='<div class="drawer-header"><span class="eyebrow">SECTEUR STRATÉGIQUE</span><button class="close" data-action="close-context" aria-label="Fermer">'+ico('cross')+'</button></div><div class="province-row"><h2>'+m.name+'</h2>'+flag(p.owner)+'</div><div class="province-row"><small>'+E.country(p.owner).name+' · '+({urban:'Capitale',plain:'Plaine',mountain:'Relief montagneux'}[m.terrain])+'</small><span class="pill '+(r.status==='war'?'red':'blue')+'">'+statusLabel(r)+'</span></div><div class="infrastructure">'+Object.entries(p.buildings).map(([k,l])=>'<span class="pill">'+E.buildings[k].name+' '+l+'</span>').join('')+'</div><div class="unit-list">'+localUnits.map(u=>'<button data-action="select-unit" data-id="'+u.id+'">'+ico(u.type==='armor'?'tank':u.type)+'<span>'+esc(u.name)+'</span><b>'+Math.round(u.hp)+' %</b></button>').join('')+'</div>'+(ours?'<div class="row"><button class="small primary" data-action="sector-build">Industrie</button><button class="small" data-action="sector-army">Recruter</button></div>':'<button class="full small blue" data-action="country-dip" data-id="'+p.owner+'">Contacter le gouvernement</button>');}
function renderUnit(){const box=$('unit-card'),u=state.units.find(u=>u.id===selectedUnit);box.hidden=!u||!started;if(box.hidden)return;const ours=u.owner===player;box.innerHTML='<div class="card-head"><div>'+ico(u.type==='armor'?'tank':u.type,'large-icon')+'<div><h3>'+esc(u.name)+'</h3><p>'+E.country(u.owner).name+' · '+E.meta(u.province).name+'</p></div></div><button class="close" data-action="close-unit" aria-label="Fermer">'+ico('cross')+'</button></div><div class="metrics"><span>ÉTAT <b>'+Math.round(u.hp)+' %</b></span><span>PUISSANCE <b>'+Math.round(E.power(u))+'</b></span><span>ENTRETIEN <b>'+E.units[u.type].upkeep+' €/min</b></span></div>'+(u.moving?'<div class="note">En route vers '+E.meta(u.moving.target).name+' · <span data-remaining="'+u.moving.due+'">'+time(u.moving.due-state.clock)+'</span></div>':ours?'<div class="row"><button class="primary" data-action="order-unit" data-id="'+u.id+'">'+ico('arrow')+' Déplacer / attaquer</button><button data-action="unit-focus" data-id="'+u.id+'">'+ico('target')+' Localiser</button></div>':'<div class="note">Unité d’un autre gouvernement. Vos ordres ne s’appliquent qu’à vos forces.</div>');}
function openModal(html,closable=true){modal.innerHTML=html;modal.dataset.closable=closable?'yes':'no';if(!modal.open)modal.showModal();}
function modalHead(eye,title){return '<div class="modal-header"><span class="eyebrow">'+eye+'</span><button class="close" data-action="close-modal" aria-label="Fermer">'+ico('cross')+'</button></div><h2 class="modal-title">'+title+'</h2>';}
function welcome(){chosen=player;welcomeRender();}
function welcomeRender(){const previous=$('leader-name')?.value||'',previousCode=$('join-code')?.value||'';openModal('<div class="welcome"><div class="welcome-intro"><img src="assets/emblem.svg" alt=""><span class="eyebrow">SOUVERAIN · EUROPE</span><h2>Votre pays.<br>Votre voix.<br>Vos décisions.</h2><p>Une Europe moderne à gouverner. Développez votre puissance et négociez l’équilibre du continent.</p><div class="feature">'+ico('globe')+' 28 nations · 72 secteurs</div><div class="feature">'+ico('tank')+' Opérations rapides sur la carte</div><div class="feature">'+ico('dip')+' Traités signés entre dirigeants</div><div class="feature">'+ico('chat')+' Canaux diplomatiques & communiqués</div><small>Scénario de jeu fictif. Les forces, budgets et temps sont équilibrés pour la partie ; ils ne représentent pas la situation militaire réelle.</small></div><div class="welcome-body"><div class="mode-tabs">'+[['local','Entraînement'],['create','Créer un salon'],['join','Rejoindre']].map(([k,l])=>'<button class="'+(startMode===k?'active':'')+'" data-action="start-mode" data-id="'+k+'">'+l+'</button>').join('')+'</div><p class="mode-description">'+({local:'Découvrez le jeu immédiatement face aux gouvernements simulés. Sauvegarde sur votre navigateur.',create:'Créez une partie partagée et invitez vos amis avec un code. Chaque joueur dirige une nation.',join:'Entrez le code de vos amis et choisissez un pays libre. Les décisions sont partagées dans le salon.'}[startMode])+'</p><div class="country-selection-label"><span>CHOISIR UNE NATION</span><b>'+E.country(chosen).name+'</b></div><div class="nation-grid">'+W.countries.map(c=>'<button class="nation-choice '+(chosen===c.id?'selected':'')+'" data-action="choose-nation" data-id="'+c.id+'">'+flag(c.id)+'<b>'+c.name+'</b></button>').join('')+'</div><div class="welcome-inputs"><div><label for="leader-name">Nom de dirigeant</label><input id="leader-name" maxlength="40" placeholder="Votre pseudo" value="'+esc(previous)+'"></div>'+(startMode==='join'?'<div><label for="join-code">Code du salon</label><input id="join-code" maxlength="8" placeholder="A1B2C3D4" value="'+esc(previousCode)+'" style="text-transform:uppercase"></div>':'')+'</div>'+(!Online.configured()&&startMode!=='local'?'<div class="offline-warning">Connexion multijoueur non configurée. Le fichier INSTALLATION.md explique comment activer Supabase ; l’entraînement fonctionne déjà.</div>':'')+'<div class="welcome-actions"><button class="primary" data-action="launch" '+(startMode!=='local'&&!Online.configured()?'disabled':'')+'>'+({local:'Prendre mes fonctions',create:'Créer la partie',join:'Rejoindre la partie'}[startMode])+' '+ico('arrow')+'</button></div>'+((saved||savedOnline)?'<div class="welcome-actions">'+(saved?'<button class="small" data-action="resume-local">Reprendre · '+E.country(saved.player).name+'</button>':'')+(savedOnline&&Online.configured()?'<button class="small" data-action="resume-online">Salon '+esc(savedOnline.code)+'</button>':'')+'</div>':'')+'<div id="launch-error" class="field-error"></div></div></div>',started);}
async function launch(){const name=$('leader-name').value.trim()||'Dirigeant '+E.country(chosen).name;if(startMode==='local'){if(saved){openModal('<div class="modal-content">'+modalHead('NOUVEAU MANDAT','Remplacer la partie locale ?')+'<p class="muted">Votre entraînement précédent sera remplacé. Vous pouvez exporter sa sauvegarde avant de commencer.</p><div class="row"><button data-action="export-saved">Exporter l’ancienne</button><button class="primary" data-action="launch-local-confirm" data-leader="'+esc(name)+'">Commencer</button></div><button class="small" data-action="welcome" style="margin-top:12px">Retour</button></div>');return;}startLocal(name);return;}
 const code=$('join-code')?.value.trim().toUpperCase();busy=true;const button=modal.querySelector('[data-action="launch"]');button.disabled=true;button.textContent='Connexion…';try{netData(await Online.rpc(startMode==='create'?'sovereign_create':'sovereign_join',startMode==='create'?{p_country:chosen,p_leader:name,p_title:'Europe · '+name}:{p_code:code,p_country:chosen,p_leader:name}));selected=null;selectedUnit=null;activePanel=null;modal.close();focusCountry(player);refresh(true);startPolling();if(startMode==='create')showRoom();}catch(e){$('launch-error').textContent=e.message;button.disabled=false;button.textContent='Réessayer';}finally{busy=false;}}
function startLocal(name){clearInterval(pollTimer);state=E.create();player=chosen;state.countries[player].leader=name;online=false;started=true;room=null;paused=false;speed=1;selected=null;selectedUnit=null;activePanel=null;save();modal.close();focusCountry(player);refresh(true);toast('Mandat commencé. Ouvrez Industrie pour votre premier investissement.');}
async function resumeOnline(){busy=true;try{netData(await Online.rpc('sovereign_sync',{p_code:savedOnline.code,p_action:null}));modal.close();focusCountry(player);refresh(true);startPolling();}catch(e){$('launch-error').textContent=e.message;}finally{busy=false;}}
function showRoom(){if(!online){welcome();startMode='create';welcomeRender();return;}openModal('<div class="modal-content">'+modalHead('SALON PRIVÉ','Invitez vos dirigeants')+'<p class="muted">Vos amis ouvrent le même site, choisissent « Rejoindre », puis entrent ce code et un pays libre.</p><div class="room-code">'+room+'</div><button class="primary full" data-action="copy-code">Copier le code</button><div class="section-head"><h3>Gouvernements du salon</h3></div>'+roomMembers.map(m=>'<div class="list-entry"><div class="row">'+flag(m.country)+'<span>'+E.country(m.country).name+'<small>'+esc(m.leader)+'</small></span></div><span class="pill '+(m.online?'green':'')+'">'+(m.online?'En ligne':'Absent')+'</span></div>').join('')+'<p class="muted">Le serveur rattrape les productions et les ordres lors des connexions. Les messages privés ne sont renvoyés qu’à leurs deux participants.</p></div>');}
function guide(){openModal('<div class="modal-content">'+modalHead('GUIDE STRATÉGIQUE','Vos premières décisions')+'<div class="helper-grid">'+[['01','Produire','Industrie ouvre les chantiers. 30 à 50 secondes pour construire ; trois niveaux maximum. Les ressources arrivent en continu.'],['02','Négocier','Diplomatie permet les échanges, alliances et cessez-le-feu. Un joueur doit signer votre proposition ; un dirigeant simulé répond sous 8 secondes.'],['03','Déplacer','Cliquez une unité, puis Déplacer / attaquer et une destination. Une route passe par vos secteurs ou ceux des alliés. Les trajets durent 6 à 85 secondes.'],['04','Faire du RP','Utilisez Messages pour négocier et Journal pour publier les discours. En salon, les messages publics et communiqués sont partagés.']].map(([n,t,b])=>'<div class="card"><strong>'+n+'</strong><h3>'+t+'</h3><p>'+b+'</p></div>').join('')+'</div><div class="divider"></div><h3>Combats et ressources</h3><p class="muted">Déclarez la guerre avant d’entrer dans un territoire adverse. À l’arrivée, le combat compare la puissance de l’unité à toutes les unités en défense. Une fortification ajoute 25 % de défense par niveau ; la montagne 20 %. Regroupez vos forces dans un secteur avant de lancer plusieurs ordres. Les assauts arrivent et sont résolus individuellement. Les avions suivent les mêmes règles de transit dans cette version.</p><p class="muted">Si vous gagnez, le secteur change de contrôle et votre unité subit des dégâts. Une attaque perdue détruit l’unité. La pénurie de ravitaillement réduit votre attaque de 35 %. Les unités en route continuent de coûter des ressources.</p><h3>Rythme et objectif</h3><p class="muted">Les délais sont ceux du jeu, avec une économie équilibrée pour des parties rapides. Contrôlez 40 secteurs pour gagner. En entraînement, pause et ×4 sont disponibles ; les pays simulés recrutent et contre-attaquent. En salon, le temps est commun et les pays non joués restent neutres jusqu’à vos actions.</p><h3>Carte et réalisme</h3><p class="muted">Les silhouettes nationales proviennent de Natural Earth. Les secteurs sont des zones de jeu autour de vraies villes, pas des régions administratives. Les voies tracées sont des liaisons stratégiques illustratives. C’est une carte tactique en 2D, avec relief graphique ; pas une caméra 3D libre.</p><button class="full primary" data-action="close-modal">Retour à la carte</button></div>');}
function settings(){openModal('<div class="modal-content">'+modalHead('PARAMÈTRES','Votre campagne')+'<div class="card"><h3>Sauvegarde d’entraînement</h3><p>Les parties locales sont sauvegardées sur ce navigateur. Exportez un fichier pour les transférer. Les parties en salon sont conservées côté serveur.</p><div class="row"><button class="small" data-action="export" '+(online?'disabled':'')+'>Exporter</button><button class="small" data-action="import" '+(online?'disabled':'')+'>Importer</button></div><input type="file" id="import-file" accept="application/json,.json" hidden></div><div class="card"><h3>Connexion multijoueur</h3><p>'+ (Online.configured()?'Configuration Supabase présente. Les salons sont disponibles.':'Pour activer les salons : exécutez supabase.sql, activez la connexion anonyme, puis renseignez config.js. Le guide INSTALLATION.md accompagne le projet.')+'</p><button class="small primary" data-action="welcome">Choisir un mode de jeu</button></div><div class="card"><h3>Carte</h3><p>Glisser pour déplacer. Molette ou + / − pour zoomer. Recherchez une ville pour la localiser. Le bouton POL / TER change la couche visuelle.</p><button class="small" data-action="map-reset">Voir toute l’Europe</button></div><div class="note">Prototype jouable : forces et économie simplifiées. Aucun nom de responsable politique réel. Les frontières représentent un fond géographique de référence, sans prise de position.</div></div>');}
function compose(){openModal('<div class="modal-content">'+modalHead('COMMUNICATION OFFICIELLE','Publier un communiqué')+'<p class="muted">Au nom de '+E.country(player).name+'. '+(online?'Visible par tous les dirigeants du salon.':'Archivé dans votre entraînement.')+'</p><label for="news-title">Titre</label><input id="news-title" maxlength="90" placeholder="Une initiative pour la paix"><label for="news-body">Déclaration</label><textarea id="news-body" maxlength="1200" rows="7" placeholder="Notre gouvernement annonce…"></textarea><button class="full primary" style="margin-top:15px" data-action="publish">Publier dans le journal</button></div>');}
function exportData(data){const blob=new Blob([JSON.stringify(data,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='souverain-europe-'+data.player+'-'+Math.floor(data.state.clock)+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function importData(file){if(!file)return;if(file.size>4e6){toast('Fichier trop volumineux.');return;}file.text().then(t=>{const data=JSON.parse(t);if(!E.valid(data.state)||!E.country(data.player))throw Error();clearInterval(pollTimer);state=data.state;player=data.player;online=false;started=true;paused=true;selected=null;selectedUnit=null;activePanel=null;save();modal.close();focusCountry(player);refresh(true);toast('Partie importée. Le temps est en pause.');}).catch(()=>toast('Sauvegarde invalide ou incompatible avec Europe V2.'));}
function selectSector(id){if(orderUnit){confirmMove(id);return;}selected=id;selectedUnit=null;renderContext();renderUnit();if(activePanel==='construction'||activePanel==='military')renderDrawer(false);dirty=true;}
function selectArmy(id){const u=state.units.find(u=>u.id===id);if(!u)return;selectedUnit=id;selected=null;renderContext();renderUnit();focusPoint(E.meta(u.province).center,Math.max(view.zoom,2.6));}
function orderMode(id){const u=state.units.find(u=>u.id===id);if(!u||u.owner!==player||u.moving)return;orderUnit=id;selectedUnit=id;activePanel=null;$('drawer').hidden=true;$('order-mode').hidden=false;$('order-mode').querySelector('span').textContent='Destination de '+u.name+' : cliquez un secteur.';renderContext();dirty=true;}
function cancelOrder(){orderUnit=null;$('order-mode').hidden=true;renderContext();dirty=true;}
function confirmMove(target){const u=state.units.find(u=>u.id===orderUnit);if(!u){cancelOrder();return;}const route=E.path(state,player,u.province,target),owner=state.provinces[target].owner,r=E.relation(state,player,owner);if(!route||target===u.province){toast('Choisissez un secteur accessible différent du départ.');return;}if(!['self','alliance','war'].includes(r.status)){toast('Cette frontière est fermée. Négociez une alliance ou déclarez la guerre.');return;}const seconds=E.duration(route,u.type),def=state.units.filter(v=>v.province===target&&!v.moving&&v.owner===owner).reduce((a,v)=>a+E.power(v),0)*(1+(state.provinces[target].buildings.fort||0)*.25+(E.meta(target).terrain==='mountain'?.2:0));openModal('<div class="modal-content">'+modalHead('ORDRE OPÉRATIONNEL',(r.status==='war'?'Assaut sur ':'Déplacement vers ')+E.meta(target).name)+'<div class="metric"><span>Unité</span><b>'+esc(u.name)+'</b></div><div class="metric"><span>Durée</span><b>'+time(seconds)+'</b></div><div class="metric"><span>Carburant</span><b>'+Math.ceil(seconds*.7)+'</b></div><div class="metric"><span>Route</span><b>'+route.length+' secteurs</b></div>'+(r.status==='war'?'<div class="note">Votre puissance : '+Math.round(E.power(u))+' · Défense estimée : '+Math.round(def)+'. Une attaque perdue détruit cette unité.</div>':'')+'<div class="row" style="margin-top:20px"><button data-action="close-modal">Retour</button><button class="'+(r.status==='war'?'danger':'primary')+'" data-action="move-confirm" data-id="'+u.id+'" data-target="'+target+'">Confirmer l’ordre</button></div></div>');}
function warModal(){openModal('<div class="modal-content">'+modalHead('DÉCISION DE GOUVERNEMENT','Déclarer la guerre à '+E.country(targetCountry).name+' ?')+'<p class="muted">Les accords commerciaux et l’alliance seront rompus. Relations : −75. Soutien : −6 points. Les opérations militaires deviennent possibles pour les deux pays.</p><div class="row"><button data-action="close-modal">Annuler</button><button class="danger" data-action="war-confirm" data-id="'+targetCountry+'">Signer la déclaration</button></div></div>');}
