 for(const ridge of ridges){const pts=ridge.map(([lon,lat])=>lonlat(lon,lat));for(let j=0;j<pts.length-1;j++){const a=pts[j],b=pts[j+1];for(let i=0;i<12;i++){const t=i/12,x=a[0]+(b[0]-a[0])*t,y=a[1]+(b[1]-a[1])*t;const shade=bc.createRadialGradient(x+.08,y+.13,0,x+.08,y+.13,.65);shade.addColorStop(0,'#111c2080');shade.addColorStop(1,'#111c2000');bc.fillStyle=shade;bc.fillRect(x-.7,y-.6,1.4,1.4);const light=bc.createRadialGradient(x-.07,y-.1,0,x-.07,y-.1,.36);light.addColorStop(0,'#d4cfac28');light.addColorStop(1,'#d4cfac00');bc.fillStyle=light;bc.fillRect(x-.5,y-.6,1,1);}}for(let offset=-2;offset<=2;offset++){bc.beginPath();pts.forEach(([x,y],i)=>{const dy=offset*.12+Math.sin(i*2.3+offset)*.08;i?bc.lineTo(x,y+dy):bc.moveTo(x,y+dy);});bc.strokeStyle=offset===0?'#c2bda523':'#29382b22';bc.lineWidth=.025;bc.stroke();}}
